transforms.result:
/* 基础页面样式 - 匹配原版 */
.presentation-page {
  background: #FAF9F7;
  font-family: var(--anthropic-font-primary);
}

/* ===== 全屏背景图片Hero区域样式 ===== */
.anthropic-hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 4rem 0 2rem;
}

/* 背景图片层 - 动态加载 */
.hero-background-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  z-index: 1;
}

/* 遮罩层确保文字清晰可见 */
.hero-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    45deg,
    rgba(0, 0, 0, 0.6) 0%,
    rgba(0, 0, 0, 0.4) 50%,
    rgba(0, 0, 0, 0.6) 100%
  );
  z-index: 2;
}

.hero-container {
  position: relative;
  z-index: 3;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
  width: 100%;
}

.hero-content-wrapper {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: flex-start;
}

.hero-bottom-left {
  max-width: 760px;
  padding: 0 0 3rem 1.5rem;
  text-align: left;
}

/* 主标题样式 - 适配全屏背景 */
.hero-main-title {
  font-size: clamp(3rem, 6vw, 5rem);
  font-weight: 700;
  line-height: 1.1;
  color: white !important;
  letter-spacing: -0.02em;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.7) !important;
  z-index: 10;
  position: relative;
  margin-bottom: 1.5rem;
  font-family: var(--anthropic-font-primary);
  position: relative;
  text-shadow: 0 4px 8px rgba(0, 0, 0, 0.5), 0 2px 4px rgba(0, 0, 0, 0.3);
  opacity: 0;
  animation: titleAppear 1.2s cubic-bezier(0.4, 0, 0.2, 1) 0.3s forwards;
}

/* 描述文字样式 */
.hero-description {
  font-size: 1.1rem;
  color: white !important;
  line-height: 1.6;
  margin-bottom: 2rem;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.7) !important;
  z-index: 10;
  position: relative;
  opacity: 0;
  animation: titleAppear 1.2s cubic-bezier(0.4, 0, 0.2, 1) 0.5s forwards;
}

@keyframes titleAppear {
  0% {
    opacity: 0;
    transform: translateY(30px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.title-highlight {
  text-decoration: underline;
  text-decoration-color: #E17B47;
  text-decoration-thickness: 3px;
  text-underline-offset: 4px;
  color: #E17B47;
}

/* 产品卡片容器 */
.hero-product-cards {
  margin-top: 2rem;
  opacity: 0;
  animation: cardsAppear 1s cubic-bezier(0.4, 0, 0.2, 1) 0.8s forwards;
}

@keyframes cardsAppear {
  0% {
    opacity: 0;
    transform: translateY(20px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.cards-row {
  gap: 1rem;
}

/* 横向卡片布局 */
.cards-horizontal-layout {
  display: flex;
  gap: 1.5rem;
  justify-content: flex-start;
  align-items: stretch;
}

/* 产品卡片样式 - 适配全屏背景 */
.hero-product-card {
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-radius: 16px;
  padding: 1.5rem;
  height: 100%;
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2), 0 4px 16px rgba(0, 0, 0, 0.1);
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 260px;
  width: 300px;
  flex-shrink: 0;
}

.hero-product-card:hover {
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.25), 0 6px 20px rgba(0, 0, 0, 0.15);
  transform: translateY(-4px);
  background: rgba(255, 255, 255, 1);
}

.card-header {
  margin-bottom: 1rem;
}

.card-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--anthropic-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.card-title {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--anthropic-text-primary);
  margin-bottom: 1rem;
  line-height: 1.3;
}

.card-description {
  font-size: 1rem;
  color: var(--anthropic-text-secondary);
  line-height: 1.5;
  margin-bottom: 2rem;
  flex-grow: 1;
}

.card-btn {
  margin-top: auto;
  font-weight: 600;
  font-size: 0.9rem;
  height: 48px;
}

.primary-btn {
  background: #1A1A1A !important;
  color: #FFFFFF !important;
  position: relative;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  border: none !important;
}

.primary-btn::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
  transition: left 0.5s;
}

.primary-btn:hover::before {
  left: 100%;
}

.primary-btn:hover {
  background: var(--text-secondary) !important;
  transform: translateY(-1px);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
}

.secondary-btn {
  border: 2px solid rgba(255, 255, 255, 0.8) !important;
  color: white !important;
  background: rgba(255, 255, 255, 0.1) !important;
  position: relative;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  backdrop-filter: blur(10px);
}

.secondary-btn:hover {
  background: white !important;
  border-color: white !important;
  color: var(--text-primary) !important;
  transform: translateY(-1px);
  box-shadow: 0 8px 25px rgba(255, 255, 255, 0.3);
}

/* 移动端响应式设计 */
@media (max-width: 768px) {
  .hero-container {
    padding: 0 1rem;
  }

  .hero-bottom-left {
    padding: 0 0 2rem 1rem;
    max-width: 100%;
  }

  .anthropic-hero {
    min-height: 100dvh;
    padding: 3rem 0 1.5rem;
  }

  .hero-main-title {
    font-size: clamp(2rem, 8vw, 3rem);
    margin-bottom: 1rem;
  }

  .hero-description {
    font-size: 1rem;
    margin-bottom: 1.5rem;
  }

  .cards-horizontal-layout {
    flex-direction: column;
    gap: 1rem;
  }

  .hero-product-card {
    width: 100%;
    min-height: 200px;
    padding: 1.2rem;
  }
}

/* 平板端 (768px - 991px) 优化 */
@media (min-width: 768px) and (max-width: 991.98px) {
  .anthropic-hero {
    min-height: 75vh;
    padding: 5rem 0 3rem;
  }

  .hero-main-title {
    font-size: clamp(2.5rem, 5vw, 3rem);
  }
}

/* 小屏幕移动端 (<480px) */
@media (max-width: 479.98px) {
  .hero-bottom-left {
    padding: 0 0 1.5rem 0.5rem;
  }

  .hero-main-title {
    font-size: clamp(1.8rem, 7vw, 2.5rem);
  }

  .hero-description {
    font-size: 0.95rem;
  }
}

/* 节点浮动动画 */
@keyframes nodeFloat {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}

/* 连接线发光动画 */
@keyframes lineGlow {
  0%, 100% {
    opacity: 0.3;
  }
  50% {
    opacity: 0.7;
  }
}

/* 滚动触发动画 */
@keyframes fadeInUp {
  0% {
    opacity: 0;
    transform: translateY(40px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeInLeft {
  0% {
    opacity: 0;
    transform: translateX(-40px);
  }
  100% {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes fadeInRight {
  0% {
    opacity: 0;
    transform: translateX(40px);
  }
  100% {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes scaleIn {
  0% {
    opacity: 0;
    transform: scale(0.9);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

/* 动画类 */
.scroll-animate {
  opacity: 0;
  transition: all 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

.scroll-animate.in-view {
  opacity: 1;
  animation: fadeInUp 0.8s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

.animate-delay-100.in-view {
  animation-delay: 0.1s;
}

.animate-delay-200.in-view {
  animation-delay: 0.2s;
}

.animate-delay-300.in-view {
  animation-delay: 0.3s;
}

.animate-delay-400.in-view {
  animation-delay: 0.4s;
}

.animate-delay-500.in-view {
  animation-delay: 0.5s;
}

/* ===== 第二区域样式 - 匹配Anthropic ===== */
.secondary-hero-section {
  background: #FAF9F7;
  padding: 3rem 0;
  position: relative;
}

.secondary-content-wrapper {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.secondary-hero-card {
  background: #F0EDE8;
  border-radius: 24px;
  padding: 3rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  border: 1px solid rgba(0, 0, 0, 0.08);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
}

.secondary-header {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.secondary-title {
  font-size: clamp(1.75rem, 3vw, 2.25rem);
  font-weight: 700;
  color: #1a1a1a;
  line-height: 1.2;
  margin: 0;
}

.secondary-description {
  font-size: 1.125rem;
  color: #4b5563;
  line-height: 1.6;
  margin: 0;
  max-width: 400px;
}

.secondary-btn-outline {
  align-self: flex-start;
  border: 1px solid #d1d5db !important;
  color: #1a1a1a !important;
  background: transparent !important;
  font-weight: 600;
  min-width: 180px;
}

.secondary-btn-outline:hover {
  background: #f9fafb !important;
}

.model-cards-container {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.model-card {
  background: #f8f9fa;
  border-radius: 16px;
  padding: 1.5rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: all 0.3s ease;
  cursor: pointer;
  border: 1px solid #e5e7eb;
}

.model-card:hover {
  background: #f1f3f4;
  transform: translateX(4px);
}

.model-header {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.model-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.5rem;
}

.model-name {
  font-size: 1.25rem;
  font-weight: 600;
  color: #1a1a1a;
  margin: 0;
}

.model-arrow {
  color: #6b7280;
  transition: all 0.3s ease;
}

.model-card:hover .model-arrow {
  color: #1a1a1a;
  transform: translateX(4px);
}

/* 响应式设计 */
@media (max-width: 991px) {
  .secondary-hero-card {
    grid-template-columns: 1fr;
    gap: 2rem;
    padding: 2rem;
    text-align: center;
  }

  .secondary-description {
    max-width: none;
  }

  .secondary-btn-outline {
    align-self: center;
  }

  .model-cards-container {
    max-width: 400px;
    margin: 0 auto;
  }
}

@media (max-width: 768px) {
  .secondary-hero-section {
    padding: 2.5rem 0;
  }

  .secondary-content-wrapper {
    padding: 0 1rem;
  }

  .secondary-hero-card {
    padding: 1.5rem;
  }

  .secondary-title {
    font-size: 1.5rem;
  }

  .secondary-description {
    font-size: 1rem;
  }

  .model-card {
    padding: 1.25rem 1.5rem;
  }
}

/* 响应式设计 */
@media (max-width: 768px) {
  .anthropic-hero {
    min-height: 70vh;
    padding: 3rem 0;
  }

  .hero-title {
    margin-bottom: 1.5rem;
  }

  .hero-subtitle {
    margin-bottom: 2rem;
  }

  .hero-cta-group {
    flex-direction: column;
    gap: 1rem;
  }

  .hero-cta-primary,
  .hero-cta-secondary {
    width: 100%;
    max-width: 280px;
  }
}

/* ===== 按照用户HTML代码的样式 ===== */
.anthropic-mission-section {
  background: #FAF9F7;
  font-family: "Noto Sans JP", "Helvetica Neue", Arial, sans-serif;
  line-height: 1.6;
  color: #333;
}

.custom-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 60px 20px;
}

/* 上部标题区域 - 修改为左右布局 */
.header-section {
  margin-bottom: 80px;
  display: flex;
  gap: 3rem;
  align-items: flex-start;
}

.header-left {
  flex: 0 0 40%;
}

.header-right {
  flex: 0 0 60%;
  padding-left: 2rem;
}

.main-title {
  font-size: 32px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0;
  color: #1a1a1a;
}

.description {
  font-size: 18px;
  line-height: 1.8;
  color: #666;
  margin: 0;
}

/* 卡片区域 */
.cards-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 30px;
  margin-top: 60px;
}

.card {
  background: white;
  border-radius: 16px;
  padding: 40px 30px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.12);
}

.card:nth-child(1) {
  background: #F0EDE8;
}

.card:nth-child(2) {
  background: #F0EDE8;
}

.card:nth-child(3) {
  background: #F0EDE8;
}

.card-icon {
  width: 60px;
  height: 60px;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
}

.card-title {
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 15px;
  color: #1a1a1a;
}

.card-content {
  font-size: 15px;
  line-height: 1.6;
  color: #666;
}

/* 响应式设计 */
@media (max-width: 768px) {
  .custom-container {
    padding: 40px 15px;
  }

  /* 移动端恢复为上下布局 */
  .header-section {
    flex-direction: column;
    gap: 2rem;
  }

  .header-left {
    flex: none;
  }

  .header-right {
    flex: none;
    padding-left: 0;
  }

  .main-title {
    font-size: 32px;
    margin-bottom: 1rem;
  }

  .description {
    font-size: 16px;
  }

  .cards-container {
    grid-template-columns: 1fr;
    gap: 20px;
    margin-top: 40px;
  }

  .card {
    padding: 30px 25px;
    height: auto;
    min-height: 250px;
  }
}

@media (max-width: 480px) {
  .main-title {
    font-size: 28px;
  }

  .card-title {
    font-size: 20px;
  }
}

.card-icon {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--anthropic-text-primary);
  opacity: 0.8;
}

.card-title {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--anthropic-text-primary);
  margin-bottom: 1rem;
  line-height: 1.3;
}

.card-description {
  font-size: 1rem;
  color: var(--anthropic-text-secondary);
  line-height: 1.5;
  margin: 0;
}

/* 响应式设计 */
@media (max-width: 991px) {
  .mission-layout {
    grid-template-columns: 1fr;
    gap: 4rem;
    text-align: center;
  }

  .mission-statement {
    padding-right: 0;
  }

  .core-values-grid {
    padding-left: 0;
  }

  .cards-horizontal-row {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

@media (max-width: 768px) {
  .anthropic-mission-section {
    padding: 2.5rem 0;
  }

  .mission-container {
    padding: 0 1rem;
  }

  .mission-layout {
    gap: 3rem;
  }

  .value-card {
    padding: 1.5rem;
  }

  .mission-title {
    font-size: 2rem;
  }

  .values-description p {
    font-size: 1rem;
  }

  .cards-horizontal-row {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }
}

/* ===== Anthropic风格服务区域样式 ===== */
.anthropic-services-section {
  padding: 8rem 0;
  background: #FAF9F7;
  position: relative;
}

.services-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.anthropic-section-title {
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 700;
  line-height: 1.2;
  color: var(--anthropic-text-primary);
  letter-spacing: -0.02em;
  margin-bottom: 1.5rem;
  font-family: var(--anthropic-font-primary);
}

.anthropic-section-description {
  font-size: clamp(1rem, 2vw, 1.125rem);
  font-weight: 400;
  line-height: 1.6;
  color: var(--anthropic-text-secondary);
  max-width: 600px;
  margin: 0 auto;
}

.anthropic-services-grid {
  display: grid;
  gap: 1px;
  background: var(--anthropic-border-light);
  border-radius: 16px;
  overflow: hidden;
  margin-top: 4rem;
}

.anthropic-service-item {
  background: #FAF9F7;
  padding: 2rem;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  border-bottom: 1px solid var(--anthropic-border-light);
}

.anthropic-service-item:last-child {
  border-bottom: none;
}

.anthropic-service-item:hover {
  background: #FAF9F7;
  transform: translateX(4px);
}

.service-content {
  max-width: 100%;
}

.service-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}

.service-title {
  font-size: 1.375rem;
  font-weight: 600;
  color: var(--anthropic-text-primary);
  margin: 0;
  line-height: 1.3;
}

.service-arrow {
  color: var(--anthropic-text-muted);
  transition: all 0.3s ease;
  opacity: 0.6;
}

.anthropic-service-item:hover .service-arrow {
  color: var(--anthropic-text-primary);
  opacity: 1;
  transform: translateX(4px);
}

.service-description {
  font-size: 1rem;
  color: var(--anthropic-text-secondary);
  line-height: 1.6;
  margin-bottom: 1.5rem;
}

.service-tags {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.service-tag {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--anthropic-text-muted);
  background: #FAF9F7;
  padding: 0.375rem 0.75rem;
  border-radius: 6px;
  border: 1px solid var(--anthropic-border-light);
  transition: all 0.3s ease;
}

.anthropic-service-item:hover .service-tag {
  background: #FAF9F7;
  border-color: var(--anthropic-border-medium);
}

/* ===== Anthropic风格统计数据区域样式 ===== */
.anthropic-stats-section {
  padding: 6rem 0;
  background: #FAF9F7;
  position: relative;
}

.stats-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.anthropic-stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 2rem;
}

.stat-card {
  text-align: center;
  padding: 1.5rem;
  background: #FAF9F7;
  border-radius: 16px;
  border: 1px solid var(--anthropic-border-light);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
  min-height: 180px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.stat-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--anthropic-accent), #fbbf24);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.stat-card:hover::before {
  opacity: 1;
}

.stat-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--anthropic-shadow-lg);
  border-color: var(--anthropic-border-medium);
