}

.mission-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6rem;
  align-items: start;
  min-height: 60vh;
}

/* 左侧使命陈述样式 */
.mission-statement {
  padding-right: 2rem;
}

