  line-height: 1.7;
  color: var(--anthropic-text-secondary);
  margin: 0;
}

/* 右侧三个价值卡片网格 - 水平排列 */
.core-values-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.value-card {
  background: #FAF9F7;
  border-radius: 16px;
