/* ===== 性能优化CSS ===== */
/* GPU硬件加速优化 */
.product-card,
.feature-card,
.hero-cta-primary,
.hero-cta-secondary,
.cta-primary-btn,
.cta-secondary-btn {
  will-change: transform;
  transform: translateZ(0);
  backface-visibility: hidden;
  perspective: 1000px;
}

/* 减少重绘和回流 */
.product-icon,
.floating,
.pulse-glow,
.magnetic-btn::before {
  will-change: transform, opacity;
}

/* 滚动时暂停复杂动画以提升性能 */
.scrolling .floating,
.scrolling .pulse-glow::after,
.scrolling .animated-gradient {
  animation-play-state: paused;
}

/* 预加载关键字体 */
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('https://fonts.gstatic.com/s/inter/v12/UcCO3FwrK3iLTeHuS_fvQtMwCp50KnMw2boKoduKmMEVuLyfAZ9hiJ-Ek-_EeA.woff2') format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+2000-206F, U+2074, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

/* 内容可见性优化 - 懒加载非关键内容 */
.feature-highlight-section,
.cta-bottom-section {
  content-visibility: auto;
  contain-intrinsic-size: 400px;
}

/* 关键渲染路径优化 */
.anthropic-hero {
  contain: layout style paint;
}

.product-cards-section {
  contain: layout;
}

/* 图片加载优化占位符 */
.image-placeholder {
  background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

/* 减少CLS（累积布局偏移） */
.product-icon-wrapper,
.hero-title,
.section-title {
  min-height: fit-content;
}

/* 优化重复动画性能 */
@supports (animation-timeline: scroll()) {
  .scroll-animate {
    animation: fadeInUp linear;
    animation-timeline: scroll();
    animation-range: entry 0% entry 50%;
  }
}

/* 降低质量模式 - 在低性能设备上自动启用 */
@media (prefers-reduced-data: reduce) {
  .floating,
  .pulse-glow,
  .animated-gradient,
  .magnetic-btn::before {
    animation: none;
  }

  .card-3d:hover {
    transform: translateY(-4px);
  }
}

/* 高刷新率屏幕优化 */
@media (min-resolution: 120dpi) {
  .product-card,
  .feature-card {
    transition-duration: 0.2s;
  }
}

/* CPU节能模式适配 */
@media (prefers-reduced-motion: reduce) and (prefers-reduced-data: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* 深色模式适配 */
.v-theme--dark .presentation-page {
  background: #121212;
}

.v-theme--dark .card {
  background: rgba(33, 33, 33, 0.8);
}

.v-theme--dark .blur {
  background-color: rgba(33, 33, 33, 0.8);
}

.v-theme--dark .bg-gray-100 {
  background-color: rgba(45, 45, 45, 0.8);
}

.v-theme--dark .bg-light {
  background-color: rgba(55, 55, 55, 0.8);
}

.v-theme--dark .text-dark {
  color: #f7fafc;
}

.v-theme--dark .text-muted {
  color: #e2e8f0;
}

/* ===== 技术能力展示区域样式 ===== */
.anthropic-capabilities-section {
  padding: 8rem 0;
  background: #FAF9F7;
  position: relative;
}

.capabilities-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
  margin-top: 4rem;
}

.capability-card {
  background: #FAF9F7;
  border-radius: 20px;
  padding: 2.5rem 2rem;
  border: 1px solid var(--anthropic-border-light);
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.capability-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(249, 115, 22, 0.03) 0%, rgba(251, 191, 36, 0.03) 100%);
  opacity: 0;
  transition: opacity 0.4s ease;
}

.capability-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--anthropic-shadow-lg);
  border-color: rgba(249, 115, 22, 0.2);
}

.capability-card:hover::before {
  opacity: 1;
}

.capability-icon-wrapper {
  width: 100px;
  height: 100px;
  margin: 0 auto 1.5rem;
  background: rgba(249, 115, 22, 0.1);
  border-radius: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.4s ease;
  position: relative;
  z-index: 2;
}

.capability-card:hover .capability-icon-wrapper {
  background: rgba(249, 115, 22, 0.15);
  transform: scale(1.05);
  box-shadow: 0 8px 24px rgba(249, 115, 22, 0.2);
}

.capability-title {
  font-size: 1.375rem;
  font-weight: 600;
  color: var(--anthropic-text-primary);
  margin-bottom: 1rem;
  line-height: 1.3;
