  position: relative;
  z-index: 2;
}

.feature-item {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--anthropic-accent);
  background: rgba(249, 115, 22, 0.1);
  padding: 0.375rem 0.75rem;
