  line-height: 1.6;
  margin: 0;
}

.philosophy-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.philosophy-illustration {
  width: 400px;
  height: 400px;
  position: relative;
}

.illustration-container {
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.floating-elements {
  position: relative;
  width: 100%;
  height: 100%;
}

.element {
  position: absolute;
  width: 12px;
  height: 12px;
  background: var(--anthropic-accent);
  border-radius: 50%;
  opacity: 0.8;
}

.element-1 {
  top: 20%;
  left: 30%;
  animation: elementFloat 6s ease-in-out infinite;
}

.element-2 {
  top: 60%;
  right: 20%;
  animation: elementFloat 6s ease-in-out infinite 1.2s;
}

.element-3 {
  bottom: 30%;
  left: 20%;
  animation: elementFloat 6s ease-in-out infinite 2.4s;
}

.element-4 {
  top: 40%;
  right: 40%;
  animation: elementFloat 6s ease-in-out infinite 3.6s;
}

.element-5 {
  bottom: 20%;
  right: 30%;
  animation: elementFloat 6s ease-in-out infinite 4.8s;
}

.central-glow {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 80px;
  height: 80px;
  background: radial-gradient(circle, rgba(249, 115, 22, 0.3) 0%, transparent 70%);
  border-radius: 50%;
  animation: centralPulse 4s ease-in-out infinite;
}

@keyframes elementFloat {
  0%, 100% {
    transform: translateY(0) rotate(0deg);
  }
  50% {
    transform: translateY(-12px) rotate(180deg);
  }
}

@keyframes centralPulse {
  0%, 100% {
    transform: translate(-50%, -50%) scale(1);
    opacity: 0.3;
  }
  50% {
    transform: translate(-50%, -50%) scale(1.2);
    opacity: 0.6;
  }
}


/* ===== 合作伙伴区域样式 ===== */
.anthropic-partners-section {
  padding: 3rem 0;
  background: #FAF9F7;
  position: relative;
}

.partners-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.partners-logos {
  margin-top: 4rem;
  width: 100%;
  max-width: 1400px;
  margin-left: auto;
  margin-right: auto;
}

/* 滚动容器样式 - 优化版本 */
.partners-scroll-container {
  position: relative;
  width: 100%;
  max-width: 1800px;
  height: 140px;
  overflow: hidden;
  display: flex;
  align-items: center;
  margin: 0 auto;
}

/* 滚动内容 - 修复重叠问题 */
.partners-scroll-content {
  display: flex;
  animation: scrollPartners 35s linear infinite;
  will-change: transform;
  white-space: nowrap;
  flex-shrink: 0;
}

/* 鼠标悬停时暂停动画 */
.partners-scroll-container:hover .partners-scroll-content {
  animation-play-state: paused;
}

/* 滚动轨道 - 修复重叠 */
.partners-scroll-track {
  display: flex;
  gap: 4rem;
  padding-right: 4rem;
  flex-shrink: 0;
  align-items: center;
}

/* 滚动动画 - 优化的循环 */
@keyframes scrollPartners {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(calc(-100% - 4rem));
  }
}

/* 左侧渐变遮罩 - 减少宽度 */
.scroll-fade-left {
  position: absolute;
  left: 0;
  top: 0;
  width: 60px;
  height: 100%;
  background: linear-gradient(to right, #FAF9F7 0%, #FAF9F7 20%, transparent 100%);
  z-index: 2;
  pointer-events: none;
}

/* 右侧渐变遮罩 - 减少宽度 */
.scroll-fade-right {
  position: absolute;
  right: 0;
  top: 0;
  width: 60px;
  height: 100%;
  background: linear-gradient(to left, #FAF9F7 0%, #FAF9F7 20%, transparent 100%);
  z-index: 2;
  pointer-events: none;
}

.partners-row-single {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 1.5rem;
  margin-bottom: 0;
}

/* 保持原有的partners-row样式以防需要回滚 */
.partners-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 2rem;
}

.partners-row:last-child {
  margin-bottom: 0;
}

.partner-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 140px;
  width: 280px;
  flex-shrink: 0;
  transition: all 0.3s ease;
}

.logo-container {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.partner-logo-image {
  max-width: 100%;
  max-height: 80px;
  width: auto;
  height: auto;
  object-fit: contain;
  transition: all 0.3s ease;
  filter: grayscale(100%) opacity(0.7);
}

.partner-logo:hover .partner-logo-image {
  filter: grayscale(0%) opacity(1);
  transform: scale(1.05);
}

.logo-placeholder {
  width: 260px;
  height: 120px;
  background: #FAF9F7;
  border: 1px solid var(--anthropic-border-light);
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
  padding: 10px;
}

.logo-placeholder::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(249, 115, 22, 0.05) 0%, rgba(251, 191, 36, 0.05) 100%);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.partner-logo:hover .logo-placeholder {
  transform: translateY(-4px);
  box-shadow: var(--anthropic-shadow-sm);
  border-color: var(--anthropic-border-medium);
}

.partner-logo:hover .logo-placeholder::before {
  opacity: 1;
}

.logo-text {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--anthropic-text-secondary);
  position: relative;
  z-index: 2;
  transition: color 0.3s ease;
  text-align: center;
  line-height: 1.3;
  word-break: keep-all;
  white-space: normal;
  max-width: 100%;
}

.partner-logo:hover .logo-text {
  color: var(--anthropic-text-primary);
}

/* ===== 响应式设计优化 ===== */
@media (max-width: 991px) {
  .philosophy-content {
    padding-right: 0;
    margin-bottom: 3rem;
  }

  .philosophy-illustration {
    width: 300px;
    height: 300px;
  }

  .news-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 2rem;
  }

  .news-view-all-btn {
    margin-left: 0;
  }

  .news-grid {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
  }

  .news-item.featured {
    grid-row: auto;
  }

  .partners-row-single {
    grid-template-columns: repeat(4, 1fr);
    gap: 1rem;
  }

  /* 平板端滚动样式优化 */
  .partners-scroll-container {
    max-width: 1200px;
    height: 120px;
  }

  .partners-scroll-track {
    gap: 3rem;
    padding-right: 3rem;
  }

  .partner-logo {
    width: 240px;
    height: 120px;
  }

  .scroll-fade-left,
  .scroll-fade-right {
    width: 50px;
  }

  .partners-row {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .anthropic-capabilities-section,
  .anthropic-philosophy-section,
  .featured-news-section,
  .anthropic-partners-section {
    padding: 2.5rem 0;
  }

  .capabilities-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .capability-card {
    padding: 2rem 1.5rem;
  }

  .philosophy-illustration {
    width: 250px;
    height: 250px;
  }

  .partners-row-single {
    grid-template-columns: repeat(2, 1fr);
    gap: 0.8rem;
  }

  /* 移动端滚动样式优化 */
  .partners-scroll-container {
    max-width: 100%;
    height: 100px;
  }

  .partners-scroll-track {
    gap: 2rem;
    padding-right: 2rem;
  }

  .partner-logo {
    width: 200px;
    height: 100px;
  }

  .scroll-fade-left,
  .scroll-fade-right {
    width: 40px;
  }

  /* 移动端减慢滚动速度 */
  .partners-scroll-content {
    animation-duration: 30s;
  }

  .partners-row {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .logo-placeholder {
    width: 180px;
    height: 80px;
  }

  /* 客户评价和FAQ区域移动端样式 */
  .anthropic-testimonials-section {
    padding: 4rem 0;
  }

  .testimonials-container {
    padding: 0 1rem;
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
    margin-top: 2.5rem;
  }

  .testimonial-card {
    padding: 1.5rem;
    border-radius: 16px;
  }

  .testimonial-quote {
    font-size: 1rem;
    line-height: 1.6;
    margin-bottom: 1.5rem;
  }

  .anthropic-faq-section {
    padding: 2.5rem 0;
  }

  .faq-container {
    padding: 0 1rem;
  }

  .faq-list {
    margin-top: 2.5rem;
  }

  .faq-item {
    margin-bottom: 0.75rem;
    padding: 1.25rem;
    border-radius: 12px;
  }

  .question-text {
    font-size: 1rem;
    line-height: 1.4;
  }

  .faq-answer {
    margin-top: 0.75rem;
    padding-top: 0.75rem;
  }

  .faq-answer p {
    font-size: 0.9rem;
    line-height: 1.5;
  }
}

/* ===== 客户评价区域样式 ===== */
.anthropic-testimonials-section {
  padding: 8rem 0;
  background: #FAF9F7;
  position: relative;
}

.testimonials-container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 2rem;
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
  margin-top: 4rem;
}

.testimonial-card {
  background: #FAF9F7;
  border-radius: 20px;
  padding: 2.5rem;
  border: 1px solid var(--anthropic-border-light);
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
}

.testimonial-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--anthropic-accent), #ff6b35);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--anthropic-shadow-lg);
  border-color: var(--anthropic-border-medium);
}

.testimonial-card:hover::before {
  transform: scaleX(1);
}

.testimonial-content {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.testimonial-quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--anthropic-text-primary);
  margin-bottom: 2rem;
  quotes: """ """ "'" "'";
  font-style: italic;
  flex-grow: 1;
}

.testimonial-quote::before {
  content: open-quote;
  font-size: 1.5em;
  color: var(--anthropic-accent);
  font-weight: bold;
  margin-right: 0.1em;
}

.testimonial-quote::after {
  content: close-quote;
  font-size: 1.5em;
  color: var(--anthropic-accent);
  font-weight: bold;
  margin-left: 0.1em;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-top: auto;
}

.author-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--anthropic-accent), #ff6b35);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.author-initial {
  color: white;
  font-weight: 600;
  font-size: 1.125rem;
}

.author-info {
  flex-grow: 1;
}

.author-name {
  font-weight: 600;
  color: var(--anthropic-text-primary);
  font-size: 1rem;
  margin-bottom: 0.25rem;
}

.author-title {
  color: var(--anthropic-text-muted);
  font-size: 0.875rem;
}

/* ===== FAQ区域样式 ===== */
.anthropic-faq-section {
  padding: 3rem 0;
  background: #FAF9F7;
  position: relative;
}

.faq-container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 2rem;
}

.faq-list {
  max-width: 800px;
  margin: 4rem auto 0;
}

.faq-item {
  background: #FAF9F7;
  border-radius: 16px;
  margin-bottom: 1rem;
  border: 1px solid var(--anthropic-border-light);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  cursor: pointer;
  padding: 1.5rem 2rem;
  overflow: hidden;
}

.faq-item:hover {
  border-color: var(--anthropic-border-medium);
  box-shadow: var(--anthropic-shadow-sm);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.question-text {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--anthropic-text-primary);
  line-height: 1.5;
  margin: 0;
  flex-grow: 1;
}

.question-icon {
  width: 24px;
  height: 24px;
  color: var(--anthropic-text-muted);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  flex-shrink: 0;
}

.question-icon.expanded {
  transform: rotate(180deg);
  color: var(--anthropic-accent);
}

.faq-answer {
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--anthropic-border-light);
  animation: fadeInAnswer 0.3s ease-out;
}

.faq-answer p {
  color: var(--anthropic-text-secondary);
  line-height: 1.6;
  font-size: 1rem;
  margin: 0;
}

@keyframes fadeInAnswer {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ===== 企業情報 - 简洁表格式布局 ===== */
.featured-section {
  padding: 3rem 0;
  background: #FAF9F7;
  border-top: 1px solid #E5E5E5;
}

.featured-content {
  display: flex;
  gap: 4rem;
  align-items: flex-start;
}

.featured-left {
  flex: 0 0 200px;
}

.featured-title {
  font-size: 2rem;
  font-weight: 600;
  color: #1A1A1A;
  margin: 0;
  letter-spacing: -0.01em;
}

.featured-right {
  flex: 1;
}

.featured-news-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.featured-news-item {
  background: transparent;
  border-bottom: 1px solid #E5E5E5;
  padding: 1.5rem 0;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
}

.featured-news-item:last-child {
  border-bottom: none;
}

.featured-news-item:hover {
  background: rgba(225, 123, 71, 0.02);
}

.featured-news-item:hover .featured-news-title {
  color: #E17B47;
}

.featured-news-content {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 2rem;
}

.featured-news-title {
  font-size: 1.125rem;
  font-weight: 500;
  color: #1A1A1A;
  line-height: 1.4;
  margin: 0;
  flex: 1;
  transition: color 0.2s ease;
}

.featured-news-meta {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-shrink: 0;
}

.featured-news-category {
  font-size: 0.875rem;
  font-weight: 500;
  color: #666666;
  text-transform: capitalize;
}

.featured-news-date {
  font-size: 0.875rem;
  color: #999999;
  font-weight: 400;
  white-space: nowrap;
}

/* 响应式设计 */
@media (max-width: 992px) {
  .featured-content {
    flex-direction: column;
    gap: 2rem;
  }

  .featured-left {
    flex: none;
  }
}

@media (max-width: 768px) {
  .featured-section {
    padding: 3rem 0;
  }

  .featured-title {
    font-size: 1.75rem;
  }

  .featured-news-content {
    flex-direction: column;
    gap: 0.75rem;
    align-items: flex-start;
  }

  .featured-news-title {
    font-size: 1rem;
  }

  .featured-news-meta {
    gap: 1rem;
  }

  .featured-news-category, 
  .featured-news-date {
    font-size: 0.8rem;
  }
}

@media (max-width: 480px) {
  .featured-title {
    font-size: 1.5rem;
  }

  .featured-news-item {
    padding: 1.25rem 0;
  }

  .featured-news-title {
    font-size: 0.95rem;
  }
}
